import * as T from 'three';import{GLTFLoader}from'./vendor/GLTFLoader.js';
const colors=[0xc22d12,0xd99a08,0x1f5793],corners=[[-3,0,1.5],[0,0,-3],[3,0,1.5]];
export async function board(el){let scene=new T.Scene();scene.background=new T.Color('#d7ddc9');let camera=new T.PerspectiveCamera(38,1,.1,100),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.shadowMap.enabled=true;el.append(renderer.domElement);scene.add(new T.HemisphereLight(0xfff8dd,0x496458,2.5));let light=new T.DirectionalLight(0xffffff,3);light.position.set(3,10,6);light.castShadow=true;light.shadow.mapSize.set(1024,1024);scene.add(light);let group=new T.Group();scene.add(group);let dynamic=new T.Group();group.add(dynamic);const mat=(c)=>new T.MeshStandardMaterial({color:c,roughness:.9});function mesh(geo,c,x,y,z,parent=group){let m=new T.Mesh(geo,mat(c));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}mesh(new T.CylinderGeometry(7.3,7.5,.35,6),0x9ead95,0,-.3,0);mesh(new T.CylinderGeometry(4.6,4.9,.35,3),0x476b5c,0,0,0).rotation.y=Math.PI/3;mesh(new T.ConeGeometry(1.2,1,3),0xc8a55c,0,.6,0).rotation.y=Math.PI/3;
const eye=new T.Group();eye.position.set(0,1.2,.3);group.add(eye);let white=mesh(new T.SphereGeometry(.38,24,12),0xfaf1d7,0,0,0,eye);white.scale.set(1.6,.65,.7);mesh(new T.SphereGeometry(.14,16,12),0x143e39,0,0,.24,eye);
function label(text,x,y,z,size=1.5){let can=document.createElement('canvas');can.width=512;can.height=128;let ctx=can.getContext('2d');ctx.fillStyle='#f7efd9';ctx.fillRect(0,0,512,128);ctx.fillStyle='#163e39';ctx.font='bold 34px Georgia';ctx.textAlign='center';ctx.fillText(text,256,78);let tx=new T.CanvasTexture(can),m=new T.Mesh(new T.PlaneGeometry(size,size/4),new T.MeshBasicMaterial({map:tx,side:T.DoubleSide}));m.rotation.x=-Math.PI/2;m.position.set(x,y,z);dynamic.add(m);return m}
let faces=await(await fetch('./assets/dice-faces.json')).json();let original=await new GLTFLoader().loadAsync('./assets/dice.glb');let base=original.scene,b=new T.Box3().setFromObject(base),sz=b.getSize(new T.Vector3()),ctr=b.getCenter(new T.Vector3());base.position.sub(ctr);let dice=[];for(let i=0;i<3;i++){let root=new T.Group(),model=base.clone(true);model.traverse(m=>{if(m.isMesh){m.material=m.material.clone();if(m.material.color.getHex()>0x333333)m.material.color.setHex(colors[i]);m.castShadow=true}});root.add(model);root.scale.setScalar(.95/Math.max(sz.x,sz.y,sz.z));group.add(root);dice.push(root)}
let angle=.2,dist=14,top=false,drag=null;el.addEventListener('pointerdown',e=>{drag=e.clientX;el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(drag!==null){angle+=(e.clientX-drag)*.008;drag=e.clientX;render()}});el.addEventListener('pointerup',()=>drag=null);el.addEventListener('wheel',e=>{e.preventDefault();dist=Math.max(10,Math.min(22,dist+e.deltaY*.01));render()},{passive:false});function render(){let w=el.clientWidth,h=el.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.position.set(Math.sin(angle)*dist,top?20:11,Math.cos(angle)*dist);if(top)camera.position.set(0,20,.01);camera.lookAt(0,0,0);camera.updateProjectionMatrix();renderer.render(scene,camera)}new ResizeObserver(render).observe(el);
return{toggle(){top=!top;render()},update(s){while(dynamic.children.length){let c=dynamic.children.pop();c.geometry?.dispose();c.material?.map?.dispose();c.material?.dispose()}dice.forEach((d,i)=>{let p=corners[s.dice[i].channel];d.position.set(p[0],.9,p[2]);d.quaternion.setFromUnitVectors(new T.Vector3(...faces.find(f=>f.value===s.dice[i].value).normal),new T.Vector3(0,1,0));label(s.dice[i].id+' · '+s.dice[i].value,p[0],.35,p[2]+1.1,1.3);label(['RESOURCES','RULES','INFLUENCE'][s.dice[i].channel],p[0],.33,p[2]-.9,2)});s.players.forEach((p,i)=>{let a=i/s.players.length*Math.PI*2+.5,x=Math.sin(a)*5.8,z=Math.cos(a)*5.8;label(p.name,x,.05,z,2.5);p.net.forEach((id,k)=>{let card=s.cards[id],m=mesh(new T.BoxGeometry(.52,.13,.8),colors[card.supply],x+(k-1)*.62,.22,z-.65,dynamic);if(s.suspended.includes(id))m.rotation.y=.5})});if(s.mode==='window')label('MARKET WINDOW · '+(s.window+1)+'–'+(s.window+2),0,.32,3.4,4);render()}}}
